import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(540, 1020)

class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        worked = [Span(600, 700), Span(650, 900)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 15:00-17:00 (120 min)"],
        )

    def test_no_workers_is_one_gap(self):
        self.assertEqual(
            find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])

    def test_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 600)], OPEN)
        with self.assertRaises(ValueError):
            find_gaps([Span(900, 1100)], OPEN)

if __name__ == "__main__":
    unittest.main()
